function converterHorario(hora, minuto) {
    let periodo = hora >= 12 ? "P.M.": A.M.";
    hora = hora % 12;
    hora = hora  == 0 ? 12 : hora;
    return `${hora):${minuto} ${periodo)`;
}
console.log(converterHorario(16, 25));

