atividades.respostaEnviada:
let idContador = 1;

const form = document.querySelector("form");
const tabela = document.querySelector("table");

form.addEventListener("submit", function (event) {
  event.preventDefault();

  const nome = document.getElementById("Nome").value;
  const sobrenome = document.getElementById("sobrenome").value;
  const posicao = document.getElementById("position").value;
  const email = nome.toLowerCase() + "@email.com";

  const novaLinha = document.createElement("tr");
  const idLinha = "linha_" + idContador;
  novaLinha.id = idLinha;

  novaLinha.innerHTML = `
    <td>${idContador}</td>
    <td>${nome} ${sobrenome}</td>
    <td>${email}</td>
    <td><button class="delete">delete</button></td>
  `;

  const primeiraLinha = tabela.querySelector("tr[id^='linha_']");

  if (posicao === "cima" && primeiraLinha) {
    primeiraLinha.before(novaLinha); 
  } else {
    tabela.append(novaLinha); 
  }

  idContador++;
});

tabela.addEventListener("click", function (event) {
  if (event.target.classList.contains("delete")) {
    const linhaParaRemover = event.target.closest("tr");
    linhaParaRemover.remove(); 
  }
});

